function targets(){return Array.from(document.querySelectorAll('button,a,input,select')).filter(e=>!e.disabled&&e.getClientRects().length&&(!document.querySelector('dialog[open]')||e.closest('dialog[open]')))}window.omniPadController=window.omniMediaController=function(a){let list=targets(),i=list.indexOf(document.activeElement);if(['left','up','right','down','l1','r1'].includes(a)){list[(i+(['left','up','l1'].includes(a)?-1:1)+list.length)%list.length]?.focus();return true}if(['cross','confirm','a'].includes(a)){document.activeElement.click();return true}if(['circle','back','b'].includes(a)){let d=document.querySelector('dialog[open]');if(d){d.close();document.querySelector('button').focus();return true}}return false};document.addEventListener('keydown',e=>{let a={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',Escape:'back'}[e.key];if(a&&window.omniPadController(a))e.preventDefault()});document.querySelector('button,a,input,select')?.focus();let entry=true,opener;const v=document.querySelector('#view'),n=document.querySelector('#notice');function draw(mode){if(window.omnibloomHost){v.textContent='Vault unavailable until the native encrypted store is connected.';n.textContent='No preview logins are loaded.';return;}n.textContent='';if(mode==='vault'){v.innerHTML=entry?'<div class="card row"><div><h2>example.com</h2><p>demo@example.com · ••••••••••••</p></div><button id="delete">Remove</button></div>':'<div class="card"><h2>No saved passwords</h2></div>';if(entry)document.querySelector('#delete').onclick=()=>{opener=document.activeElement;document.querySelector('#confirm').showModal();document.querySelector('#cancel').focus()}}if(mode==='save')v.innerHTML='<div class="card"><h2>Save this login for example.com?</h2><p>demo@example.com · ••••••••••••</p><div class="actions"><button id="save" class="primary">Save login</button><button id="never">Never for this site</button></div></div>';if(mode==='fill')v.innerHTML='<div class="card"><h2>Use a saved login on example.com</h2><p>Only logins matching this page’s verified origin appear.</p><button id="fill">demo@example.com</button></div>';if(mode==='settings')v.innerHTML='<div class="card"><label><span>Offer to save passwords</span><select><option>On</option><option>Off</option></select></label><label><span>Autofill</span><select><option>Ask every time</option><option>Off</option></select></label><label><span>Lock vault</span><select><option>When Omni closes</option><option>After 5 minutes</option></select></label><p>Settings are a preview and reset when this page reloads.</p></div>';['save','never','fill'].forEach(id=>{const b=document.getElementById(id);if(b)b.onclick=()=>{n.textContent=id==='fill'?'Preview: no password was filled.':id==='save'?'Preview: no password was stored.':'Preview: site exclusion selected.'}})}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>draw(b.dataset.view));document.querySelector('#cancel').onclick=()=>{document.querySelector('#confirm').close();opener.focus()};document.querySelector('#remove').onclick=()=>{entry=false;document.querySelector('#confirm').close();draw('vault');document.querySelector('[data-view=vault]').focus()};document.querySelector('#confirm').addEventListener('cancel',()=>setTimeout(()=>opener.focus(),0));draw('vault');